style.css:
@-moz-document domain("tiktok.com") {
/* fundo */
body {
    background-color: #fff5f7 !important;
}

/* sidebar */
aside {
    background-color: #ffeef2 !important;
}

/* textos */
span, p {
    color: #000 !important;
}

/* vídeos (não mexe muito pra não bugar) */
div[data-e2e="recommend-list-item"] {
    border-radius: 12px;
}

/* hover suave */
div:hover {
    background-color: rgba(255, 182, 193, 0.08);
}
}
